    v_new := replace(v_new, v_h.b, v_h.a);
  END LOOP;
  IF md5(v_new) <> '7bbb85d8de29b0b4c6a3e6da7e211a4e' THEN
    RAISE EXCEPTION '095 rollback: public.plan_seg_fix(jsonb,text,text) would not be its live text (md5 %)', md5(v_new);
  END IF;
  EXECUTE format('CREATE OR REPLACE FUNCTION %s(%s) RETURNS %s LANGUAGE plpgsql %s %s SET search_path = public AS %L',
    split_part('public.plan_seg_fix(jsonb,text,text)', '(', 1), pg_get_function_arguments(p.oid), pg_get_function_result(p.oid),
    CASE p.provolatile WHEN 'i' THEN 'IMMUTABLE' WHEN 's' THEN 'STABLE' ELSE 'VOLATILE' END,
    CASE WHEN p.prosecdef THEN 'SECURITY DEFINER' ELSE 'SECURITY INVOKER' END, v_new);
  IF (SELECT md5(prosrc) FROM pg_proc WHERE oid = 'public.plan_seg_fix(jsonb,text,text)'::regprocedure) <> '7bbb85d8de29b0b4c6a3e6da7e211a4e'
     OR (SELECT proacl::text FROM pg_proc WHERE oid = p.oid) IS DISTINCT FROM p.proacl::text THEN
    RAISE EXCEPTION '095 rollback proof: public.plan_seg_fix(jsonb,text,text) is not back to its live text with its rights';
  END IF;
  RAISE NOTICE '095 ROLLBACK OK';
END $do$;
